import{_ as a,H as s,f as t,i as o}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"subagents","description":"","frontmatter":{},"headers":[],"relativePath":"zh/skills/subagents.md","filePath":"zh/skills/subagents.md"}'),d={name:"zh/skills/subagents.md"};function l(n,e,c,i,r,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="subagents" tabindex="-1">subagents <a class="header-anchor" href="#subagents" aria-label="Permalink to &quot;subagents&quot;">​</a></h1><p><code>subagents</code> 技能将计划中标记为 <code>[parallel]</code> 的独立里程碑派发给具备独立上下文窗口的 Subagent，通过明确的角色契约与可选能力分级路由实现并行执行与交叉评审。</p><h2 id="派发与写作用域隔离" tabindex="-1">派发与写作用域隔离 <a class="header-anchor" href="#派发与写作用域隔离" aria-label="Permalink to &quot;派发与写作用域隔离&quot;">​</a></h2><p>仅在派发时刻将里程碑展开为原子步骤；向 Subagent 传递规范与计划文件路径，严禁大段粘贴正文内容：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK: &lt;一句话任务&gt;</span></span>
<span class="line"><span>ROLE: &lt;implementer | spec-reviewer | quality-reviewer&gt;</span></span>
<span class="line"><span>MODEL: &lt;fast | balanced | strongest&gt;</span></span>
<span class="line"><span>REPOSITORY / MODULE / FILES / SPEC / ACCEPTANCE / EXTRA</span></span></code></pre></div><p>每条任务拥有单一仓库与模块写入边界，禁止向重叠模块根目录同时派发多个写者。仅当依赖模块均报告本地验收通过后才派发集成任务，且仅由协调者勾选 <code>- [x]</code>。</p><h2 id="任务闭环与状态处理" tabindex="-1">任务闭环与状态处理 <a class="header-anchor" href="#任务闭环与状态处理" aria-label="Permalink to &quot;任务闭环与状态处理&quot;">​</a></h2><p>单任务执行闭环：<code>implementer</code>（默认 <code>balanced</code>） → <code>spec-reviewer</code>（默认 <code>fast</code>） → <code>quality-reviewer</code>（默认 <code>strongest</code>） → 协调者勾选完成。协调者按状态协议处理返回：</p><ul><li><code>DONE_WITH_CONCERNS</code>：涉及正确性则立刻处理，属观察性提醒则记录。</li><li><code>NEEDS_CONTEXT</code>：补充缺失事实后重新派发。</li><li><code>BLOCKED</code>：诊断阻塞根因（缺失上下文 / 能力分级不足 / 任务过大 / 计划有误），严禁盲目重试。</li></ul><h2 id="模型分级" tabindex="-1">模型分级 <a class="header-anchor" href="#模型分级" aria-label="Permalink to &quot;模型分级&quot;">​</a></h2><p><code>MODEL</code>（<code>fast | balanced | strongest</code>）缺省使用宿主默认模型；也可通过 <code>.praxis/model-tiers.yaml</code> 映射具体模型（解析顺序：项目 <code>.praxis/model-tiers.yaml</code> → 用户 <code>~/.praxis/model-tiers.yaml</code> → 宿主默认模型；模板见仓库根目录 <code>model-tiers.example.yaml</code> 的 <code>tiers.&lt;tier&gt;.{provider, model}</code> 结构）。</p>`,11)])])}const m=a(d,[["render",l]]);export{h as __pageData,m as default};
